import{_ as t,o as i,c as o,a5 as e}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Thiết kế DA-570: Tiền xử lý văn bản và Chuẩn hóa dữ liệu (Ingestion, Bot Filter, NLP)","description":"","frontmatter":{},"headers":[],"relativePath":"ai-models/DA-570-text-normalization-pipeline-design.md","filePath":"ai-models/DA-570-text-normalization-pipeline-design.md"}'),r={name:"ai-models/DA-570-text-normalization-pipeline-design.md"};function c(a,n,g,h,s,l){return i(),o("div",null,[...n[0]||(n[0]=[e('<h1 id="thiet-ke-da-570-tien-xu-ly-van-ban-va-chuan-hoa-du-lieu-ingestion-bot-filter-nlp" tabindex="-1">Thiết kế DA-570: Tiền xử lý văn bản và Chuẩn hóa dữ liệu (Ingestion, Bot Filter, NLP) <a class="header-anchor" href="#thiet-ke-da-570-tien-xu-ly-van-ban-va-chuan-hoa-du-lieu-ingestion-bot-filter-nlp" aria-label="Permalink to &quot;Thiết kế DA-570: Tiền xử lý văn bản và Chuẩn hóa dữ liệu (Ingestion, Bot Filter, NLP)&quot;">​</a></h1><h2 id="_1-muc-tieu-objective" tabindex="-1">1. Mục tiêu (Objective) <a class="header-anchor" href="#_1-muc-tieu-objective" aria-label="Permalink to &quot;1. Mục tiêu (Objective)&quot;">​</a></h2><p>Xây dựng các tầng tiền xử lý đầu tiên (T0, T1, T2) cho hệ thống AI-05 Trend Detection Pipeline nhằm mục đích:</p><ul><li><strong>T0 - Ingestion:</strong> Nạp và chuẩn hóa cấu trúc dữ liệu thô từ Social Listening.</li><li><strong>T1 - Bot/Spam Filter:</strong> Lọc bỏ các tài khoản giả mạo, clone, spam và seeding trước khi đưa vào phân tích để đảm bảo tính trung thực của xu hướng.</li><li><strong>T2 - NLP Preprocessing:</strong> Làm sạch văn bản, chuẩn hóa từ lóng và tách từ tiếng Việt để chuẩn bị cho các mô hình đánh giá đột biến và đồ thị phía sau.</li></ul><h2 id="_2-kien-truc-t0-—-ingestion-parse-dedup" tabindex="-1">2. Kiến trúc T0 — Ingestion (Parse + Dedup) <a class="header-anchor" href="#_2-kien-truc-t0-—-ingestion-parse-dedup" aria-label="Permalink to &quot;2. Kiến trúc T0 — Ingestion (Parse + Dedup)&quot;">​</a></h2><p><strong>Đầu vào:</strong> File JSON thô xuất ra từ các công cụ crawl mạng xã hội (Facebook, v.v.).</p><p><strong>Quy trình xử lý:</strong></p><ol><li><strong>Parse dữ liệu:</strong> Đọc các file JSON/NDJSON với nhiều định dạng lồng nhau (vd: <code>data.posts</code>).</li><li><strong>Trích xuất trường thông tin (Extraction):</strong><ul><li>Nội dung (<code>text</code>, <code>raw</code>, <code>message</code>, <code>content</code>).</li><li>Tác giả (<code>user_name</code>, <code>from</code>, <code>author</code>).</li><li>Tương tác: Lấy đủ 7 loại Reaction (like, love, care, haha, wow, sad, angry).</li><li>Dữ liệu lan truyền: <code>shares</code>, <code>comments</code>, <code>topComments</code>, <code>hashtags</code>, thời gian, video/group.</li></ul></li><li><strong>Khử trùng lặp (Deduplication 2 lớp):</strong><ul><li><strong>URL dedup:</strong> Bỏ qua các post trùng lặp chính xác về URL.</li><li><strong>Text hash dedup:</strong> Mã hóa (hash) 100 ký tự đầu tiên đã được chuẩn hóa để phát hiện bài đăng copy-paste (re-share khác URL) và bỏ qua.</li></ul></li></ol><p><strong>Đầu ra:</strong> Object bài đăng (Post objects) đã được chuẩn hóa cấu trúc và loại bỏ trùng lặp.</p><h2 id="_3-kien-truc-t1-—-bot-clone-spam-filter" tabindex="-1">3. Kiến trúc T1 — Bot / Clone / Spam Filter <a class="header-anchor" href="#_3-kien-truc-t1-—-bot-clone-spam-filter" aria-label="Permalink to &quot;3. Kiến trúc T1 — Bot / Clone / Spam Filter&quot;">​</a></h2><p><strong>Đầu vào:</strong> Nội dung bình luận thô (<code>topComments</code>), ID tác giả (<code>author.id</code>), và thời gian đăng (<code>time</code>). Yêu cầu phải nhận text thô (chưa xóa URL/Emoji).</p><p><strong>Cơ chế phát hiện và xử lý dựa trên 5 Rule (KB):</strong></p><ul><li><strong>KB1 - Velocity:</strong> Nếu độ dài bình luận &gt; 50 ký tự nhưng xuất hiện &lt; 5 giây sau khi bài post được đăng $\\rightarrow$ <strong>Hành động: DROP</strong> (Bot tự động).</li><li><strong>KB2 - Frequency:</strong> Cùng một ID bình luận liên tục trên &gt; 10 bài viết trong vòng &lt; 5 phút $\\rightarrow$ <strong>Hành động: BLACKLIST</strong> toàn bộ ID.</li><li><strong>KB3A - Brigading:</strong> Số lượng bình luận chiếm áp đảo (Comments/Total Reactions &gt; 10) trong khi tổng số lượng tương tác rất thấp (&lt; 20) $\\rightarrow$ <strong>Hành động: FLAG anomaly</strong> (Gắn cờ để giảm trọng số ở tầng Engagement T5, KHÔNG DROP).</li><li><strong>KB3B - Like-buying:</strong> Lượng tương tác lớn (&gt; 500) nhưng số bình luận rất ít (&lt; 5) HOẶC đa dạng cảm xúc (reaction diversity) &lt; 2 loại $\\rightarrow$ <strong>Hành động: FLAG fake_like</strong> (Gắn cờ giảm trọng số ở T5).</li><li><strong>KB5 - Burst (Spam hàng loạt):</strong> Xuất hiện &gt; 5 ID khác nhau bình luận trên 1 bài trong &lt; 30 giây với độ đa dạng nội dung (text diversity) &lt; 0.3 $\\rightarrow$ <strong>Hành động: BLACKLIST</strong>.</li><li><strong>KB6 - Cross-post (Tín hiệu Trend):</strong> Cùng một nội dung bình luận (có nghĩa) xuất hiện ở nhiều bài viết bởi nhiều ID khác nhau $\\rightarrow$ Không phải filter mà là <strong>Tín hiệu lan truyền</strong>. Ghi nhận vào <code>trendSignals[]</code> để <strong>Boost (Tăng trọng số)</strong> ở tầng T4 và T6.</li></ul><p><strong>Đầu ra:</strong> Danh sách comment sạch (đã drop spam), danh sách blacklist, và tín hiệu trend (trendSignals).</p><h2 id="_4-kien-truc-t2-—-nlp-preprocessing" tabindex="-1">4. Kiến trúc T2 — NLP Preprocessing <a class="header-anchor" href="#_4-kien-truc-t2-—-nlp-preprocessing" aria-label="Permalink to &quot;4. Kiến trúc T2 — NLP Preprocessing&quot;">​</a></h2><p><strong>Đầu vào:</strong> Văn bản bài đăng sau khi đã được lọc từ T1.</p><p><strong>Quy trình chuẩn hóa:</strong></p><ol><li><strong>Cleaning:</strong> Loại bỏ các thành phần rác (URLs, HTML tags, hashtags, emojis).</li><li><strong>Normalize Unicode:</strong> Áp dụng chuẩn NFKC (chuyển các font chữ đặc biệt, in đậm toán học về ASCII) và chuẩn hóa về dạng dựng sẵn NFC.</li><li><strong>Lowercase &amp; Strip:</strong> Đưa về chữ in thường, xóa ký tự đặc biệt (chỉ giữ lại hệ ký tự Vietnamese Latin Extended).</li><li><strong>Tokenization (Tách từ):</strong> Phân mảnh văn bản bằng dấu cách, dựa trên cấu trúc đã được tách sẵn của thư viện Underthesea.</li><li><strong>Slang Mapping:</strong> Thay thế từ lóng/teencode bằng từ điển tự định nghĩa (~90 rules). Ví dụ: <code>ko</code> $\\rightarrow$ <code>không</code>, <code>vl</code> $\\rightarrow$ <code>rất</code>, <code>dc</code> $\\rightarrow$ <code>được</code>.</li><li><strong>Stopword Removal:</strong> Loại bỏ các từ vô nghĩa không đóng góp vào xu hướng (~150 từ stopword tiếng Việt), và bỏ các ký tự ASCII đơn lẻ (vẫn giữ lại các từ tiếng Việt 1 ký tự có nghĩa như <code>ý</code>, <code>ở</code>, <code>ạ</code>).</li></ol><p><strong>Đầu ra:</strong> Mảng Token sạch sẽ chuẩn bị cho việc phát hiện đột biến BM25.</p><p>� �</p>',20)])])}const p=t(r,[["render",c]]);export{u as __pageData,p as default};
